import json
from playwright.sync_api import sync_playwright
prov=json.load(open('/tmp/prov.json')); B='http://localhost:8765/'; erros=[]; n=0
def ok(m):
    global n; n+=1; print('ok ',m)
with sync_playwright() as p:
    br=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg=br.new_page(viewport={'width':1400,'height':900}, locale='pt-BR')
    pg.on('pageerror', lambda e: erros.append('PAGEERR '+str(e)))
    pg.add_init_script("try{localStorage.setItem('jornada_gas_url','http://localhost:8765/exec')}catch(e){}")
    pg.goto(B); pg.fill('#login-email','marques.marcela@estacio.br'); pg.fill('#login-senha',prov['admin']); pg.click('#btn-entrar')
    pg.wait_for_selector('#form-troca:not([hidden])'); pg.fill('#troca-atual',prov['admin']); pg.fill('#troca-nova','Admin2026b'); pg.fill('#troca-conf','Admin2026b'); pg.click('#form-troca button.primario')
    pg.wait_for_function("document.body.dataset.tela==='app'")
    pg.goto(B+'#/s/provas'); pg.wait_for_timeout(2500)
    f=[x for x in pg.frames if 'sistema=provas' in x.url][0]; f.wait_for_function("Motor.estado.alunos.length===3", timeout=15000)
    f.wait_for_timeout(1500)
    assert 'Ao vivo' in f.inner_text('#sync'); ok('sincronização funcionando (Ao vivo)')
    cards=f.inner_text('.cartoes').replace('\n',' '); print('   cartões:',cards)
    assert 'TOTAL ELEGÍVEIS' in cards.upper() and 'FALTA AGENDAR' in cards.upper() and 'FEZ AS PROVAS' in cards.upper(); ok('cartões do sistema antigo (total, falta agendar, faltou, agendou, fez, EAD, presencial)')
    linha=f.inner_text('tr[data-mat="202301000100"]'); assert '3 disciplinas' in linha and 'Falta agendar' in linha, linha; ok('AV: quantidade de disciplinas que falta agendar')
    l2=f.inner_text('tr[data-mat="202301000102"]'); import re; assert re.search(r'\d{2}/\d{2}/\d{2}', l2) and 'Agendou' in l2, l2; ok('próxima prova em dd/mm/aa')
    l4=f.inner_text('tr[data-mat="202301000104"]'); assert 'WhatsApp' in l4 and 'Angelica' in l4 and 'Engajamento' in l4, l4; ok('último acionamento traz o do Engajamento (data, canal, atendente)')
    f.click('[data-card="falta"]'); f.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==1; ok('cartão Falta agendar filtra a lista')
    f.click('[data-card=""]'); f.select_option('#f-tipo','avs'); f.wait_for_timeout(300)
    assert f.locator('tr[data-mat]').count()==2 and 'faltou em 1' in f.inner_text('tr[data-mat="202301000104"]'); ok('tipo AVS: 2 elegíveis, aluno que faltou aparece para reagendar')
    f.select_option('#f-tipo','av'); f.select_option('#f-canal','WhatsApp'); f.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==1; ok('filtro por canal do acionamento')
    f.select_option('#f-canal',''); f.select_option('#f-situacao','sem'); f.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==2; ok('filtro sem acionamento considera o Engajamento')
    f.select_option('#f-situacao',''); d=f.evaluate("(()=>{const x=new Date(Date.now()+2*864e5);return x.toISOString().slice(0,10)})()")
    f.fill('#f-de',d); f.dispatch_event('#f-de','change'); f.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==1; ok('filtro de data da próxima prova')
    f.fill('#f-de',''); f.dispatch_event('#f-de','change')
    pg.mouse.move(900,500); pg.screenshot(path='/home/claude/testes/tela_provas.png')
    f.click('[data-aba=dashboard]'); f.wait_for_timeout(500); t=f.inner_text('#area').lower()
    assert 'av no polo' in t and 'avs no polo' in t and 'disciplina(s) a agendar' in t and 'próximos 14 dias' in t and 'faltou' in t, t[:500]; ok('dashboard com AV e AVS: falta agendar, disciplinas, faltou, agendou, fez, provas nos próximos 14 dias, cursos')
    pg.screenshot(path='/home/claude/testes/tela_provas_dash.png', full_page=True)
    f.click('[data-aba=produtividade]'); f.wait_for_timeout(300); f.select_option('#per','tudo'); f.wait_for_timeout(300)
    t=f.inner_text('#area'); assert 'Angelica' in t and 'NO ENGAJAMENTO' in t.upper(), t[:400]; ok('produtividade conta os acionamentos feitos no Engajamento')
    f.uncheck('#com-eng'); f.wait_for_timeout(300); assert 'Angelica' not in f.inner_text('#area'); ok('dá para ver só os acionamentos feitos em Provas')
    f.check('#com-eng'); pg.screenshot(path='/home/claude/testes/tela_provas_prod.png')
    br.close()
print(n,'passos ok'); print('erros:', erros or 'nenhum')
